import { _decorator, Button, Component, Prefab, ProgressBar, resources } from "cc";

const { ccclass, property } = _decorator;

@ccclass('Loading')
export class Loading extends Component {

    @property(ProgressBar)
    progressBar: ProgressBar = null;

    @property(Button)
    joginGame: Button = null;

    private preloadList: string[] = [
        'prefab',
        'prefab/game',
        'prefab/gameEndScore',
        'prefab/gameEndScoreRank',
        'prefab/room'
    ];

    private prefabNames: string[] = [];
    private total = 0;
    private finished = 0;

    start() {
        // this.loadPrefabs().then(() => {
        //     // this.loadMainScene();
        // });
        resources.loadDir('prefab', Prefab, (err, assets) => {
            if (err) {
                console.error('加载预制体目录失败', err);
                return;
            }

            this.prefabNames = assets.map(assets => assets.name);
            this.total = this.prefabNames.length;

            this.loadPrefabsSequentially().then(() => {
                // this.loadMainScene();
            });
        });
    }

    private async loadPrefabsSequentially() {
        for (const name of this.prefabNames) {
            await this.loadOne(`prefab/${name}`);
            this.finished++;
            this.updateProgress();
        }
    }

    private loadOne(path: string): Promise<void> {
        return new Promise((resolve) => {
            resources.load(path, Prefab, (err, prefab) => {
                if (err) {
                    console.warn(`加载失败：${path}`, err);
                }
                resolve();
            });
        });
    }
    private updateProgress(progress?: number) {
        let p = progress ?? (this.finished / (this.total + 1));
        this.progressBar.progress = p;
        // this.tipLabel.string = `加载中 ${Math.floor(p * 100)}%`;
        // this.tipLabel.string = `初始化中 ${Math.floor(p * 100)}%`;
    }

}